{
  "titre": "Understanding Supply and Demand",
  "objectifGeneral": "Apply supply and demand analysis to real-world economic scenarios by analyzing a case study.",
  "notionsPivots": [
    "market equilibrium",
    "demand curve",
    "supply curve",
    "price mechanism",
    "market forces",
    "shortage and surplus"
  ],
  "etapes": [
    {
      "titre": "Discover the Basics at Home",
      "objectif": "Analyze foundational concepts of supply and demand.",
      "cartes": [
        {
          "titre": "Introduction to Supply and Demand",
          "objectif": "Identify key terms in supply and demand theory",
          "module": "CoursePresentation",
          "palier": "decouverte",
          "duree": 15,
          "consigne": "Watch the video explaining supply and demand, then review the provided definitions and examples of market equilibrium to understand their role."
        },
        {
          "titre": "Check Your Understanding",
          "objectif": "Validate comprehension of fundamental principles",
          "module": "SingleChoiceSet",
          "palier": "decouverte",
          "duree": 10,
          "consigne": "Complete the multiple-choice quiz to verify your grasp of supply and demand curves and their interactions."
        }
      ]
    },
    {
      "titre": "Solve a Case Study Together",
      "objectif": "Collaboratively analyze a real-world economic scenario",
      "cartes": [
        {
          "titre": "Group Case Solving",
          "objectif": "Interpret market outcomes in a provided scenario",
          "module": "Devoir",
          "palier": "transfert",
          "duree": 30,
          "consigne": "In-class, work in small groups to analyze the given case study: identify how shifts in supply or demand affect market equilibrium, price, and quantities. Prepare to present your findings."
        }
      ]
    },
    {
      "titre": "Review and Reflect",
      "objectif": "Consolidate insights from the case study analysis",
      "cartes": [
        {
          "titre": "Apply Concepts Beyond the Case",
          "objectif": "Demonstrate understanding through additional examples",
          "module": "test_elea",
          "palier": "entrainement",
          "duree": 20,
          "consigne": "Take the final quiz to apply supply and demand concepts to new examples. Review your responses to identify strengths and areas for improvement."
        }
      ]
    }
  ]
}
